FIREBASE_HOST = "firebasestorage.googleapis.com"
SLUG_RE = re.compile(r"^[a-z0-9]+(?:-[a-z0-9]+)*$")


def host_of(url: str) -> str:
    return urllib.parse.urlparse(url).netloc.lower()


def firebase_alternatives(url: str) -> list[str]:
    """Retorna endpoints equivalentes para uma URL do Firebase Storage.

    O primeiro item é sempre a URL original. As alternativas usam os endpoints
    oficiais da API JSON do Cloud Storage e só são tentadas se a original falhar.
    """
    parsed = urllib.parse.urlsplit(url)
    if parsed.netloc.lower() != FIREBASE_HOST:
        return [url]
    parts = parsed.path.split('/')
    # /v0/b/<bucket>/o/<object>
    try:
        b_index = parts.index('b')
        o_index = parts.index('o')
        bucket = parts[b_index + 1]
        object_name = '/'.join(parts[o_index + 1:])
    except (ValueError, IndexError):
        return [url]
    query = parsed.query
    return list(dict.fromkeys([
        url,
        f"https://storage.googleapis.com/download/storage/v1/b/{bucket}/o/{object_name}?{query}",
        f"https://www.googleapis.com/download/storage/v1/b/{bucket}/o/{object_name}?{query}",
    ]))


def read_json_bytes(data: bytes) -> object:
    text = data.decode('utf-8-sig')
    return json.loads(text)


def request_bytes(url: str, timeout: int) -> tuple[bytes, str, int]:
    req = urllib.request.Request(
        url,
        method='GET',
        headers={
            'Accept': 'application/json, text/plain;q=0.9, */*;q=0.5',
            'User-Agent': 'Oratio-JSON-Downloader/2.0 (+GitHub Actions)',
        },
    )
    with urllib.request.urlopen(req, timeout=timeout) as response:
        data = response.read()
        status = getattr(response, 'status', 200)
        final_url = response.geturl()
    if not data:
        raise ValueError('resposta vazia')
    return data, final_url, status


def download_source(item: dict, args: argparse.Namespace) -> dict:
    slug = item['slug']
    url = item['url']
    if not SLUG_RE.fullmatch(slug):
        raise ValueError(f'slug inválido: {slug}')

    errors: list[str] = []
    candidates = firebase_alternatives(url)
    for attempt in range(1, args.retries + 1):
        for endpoint_index, endpoint in enumerate(candidates, start=1):
            try:
                print(f"[{slug}] tentativa {attempt}/{args.retries}, endpoint {endpoint_index}/{len(candidates)}", flush=True)
                data, final_url, status = request_bytes(endpoint, args.timeout)
                parsed = read_json_bytes(data) if args.validate_json else None
                target = args.output / f"{slug}.json"
                target.write_bytes(data)
                return {
                    'slug': slug,
                    'status': 'concluido',
                    'host': host_of(url),
                    'bytes': len(data),
                    'sha256': hashlib.sha256(data).hexdigest(),
                    'http_status': status,
                    'source_url': url,
                    'final_url': final_url,
                    'endpoint_used': endpoint,
                    'json_type': type(parsed).__name__ if args.validate_json else '',
                    'attempt': attempt,
                    'error': '',
                }
            except urllib.error.HTTPError as exc:
                retry_after = exc.headers.get('Retry-After') if exc.headers else None
                errors.append(f"HTTP {exc.code} em {endpoint}")
                # 404/410 normalmente indicam URL inválida; ainda testamos outro endpoint.
                if exc.code == 429 and retry_after:
                    try:
                        time.sleep(min(args.max_backoff, max(1, int(retry_after))))
                    except ValueError:
                        pass
            except (urllib.error.URLError, TimeoutError, socket.timeout, ValueError, UnicodeError, json.JSONDecodeError) as exc:
                errors.append(f"{type(exc).__name__}: {exc} em {endpoint}")
            except Exception as exc:  # mantém o relatório completo sem encerrar o lote
                errors.append(f"{type(exc).__name__}: {exc} em {endpoint}")

        if attempt < args.retries:
            wait = min(args.max_backoff, args.base_backoff * (2 ** (attempt - 1)) + random.uniform(0, 3))
            print(f"[{slug}] aguardando {wait:.1f} s antes da nova tentativa", flush=True)
            time.sleep(wait)

    return {
        'slug': slug,
        'status': 'erro',
        'host': host_of(url),
        'bytes': 0,
        'sha256': '',
        'http_status': '',
        'source_url': url,
        'final_url': '',
        'endpoint_used': '',
        'json_type': '',
        'attempt': args.retries,
        'error': ' | '.join(errors[-12:]),
    }


def write_reports(rows: list[dict], output: Path) -> None:
    report_json = output / '_relatorio_download.json'
    report_csv = output / '_relatorio_download.csv'
    summary = {
        'generated_at': datetime.now(timezone.utc).isoformat(),
        'total': len(rows),
        'completed': sum(r['status'] == 'concluido' for r in rows),
        'failed': sum(r['status'] == 'erro' for r in rows),
        'items': rows,
    }
    report_json.write_text(json.dumps(summary, ensure_ascii=False, indent=2), encoding='utf-8')
    fields = list(rows[0].keys()) if rows else ['slug', 'status']
    with report_csv.open('w', encoding='utf-8-sig', newline='') as fp:
        writer = csv.DictWriter(fp, fieldnames=fields)
        writer.writeheader()
        writer.writerows(rows)


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser()
    parser.add_argument('--scope', choices=['firebase', 'browser', 'all'], default='firebase')
    parser.add_argument('--output', type=Path, default=Path('downloads'))
    parser.add_argument('--min-delay', type=float, default=2.0)
    parser.add_argument('--max-delay', type=float, default=5.0)
    parser.add_argument('--batch-size', type=int, default=12)
    parser.add_argument('--batch-pause', type=float, default=25.0)
    parser.add_argument('--retries', type=int, default=4)
    parser.add_argument('--timeout', type=int, default=90)
    parser.add_argument('--base-backoff', type=float, default=15.0)
    parser.add_argument('--max-backoff', type=float, default=120.0)
    parser.add_argument('--no-validate-json', dest='validate_json', action='store_false')
    parser.set_defaults(validate_json=True)
    return parser.parse_args()


def main() -> int:
    args = parse_args()
    if args.min_delay < 0 or args.max_delay < args.min_delay:
        raise SystemExit('intervalos inválidos')
    args.output.mkdir(parents=True, exist_ok=True)

    if args.scope == 'firebase':
        selected = [x for x in SOURCES if host_of(x['url']) == FIREBASE_HOST]
    elif args.scope == 'browser':
        selected = [x for x in SOURCES if host_of(x['url']) != FIREBASE_HOST]
    else:
        selected = list(SOURCES)

    print(f"Fontes selecionadas: {len(selected)}", flush=True)
    rows: list[dict] = []
    for index, item in enumerate(selected, start=1):
        print(f"\n{index}/{len(selected)} — {item['slug']}.json", flush=True)
        row = download_source(item, args)
        rows.append(row)
        print(f"Resultado: {row['status']}", flush=True)
        write_reports(rows, args.output)
        if index < len(selected):
            if args.batch_size > 0 and index % args.batch_size == 0:
                wait = args.batch_pause
                print(f"Pausa preventiva entre lotes: {wait:.1f} s", flush=True)
            else:
                wait = random.uniform(args.min_delay, args.max_delay)
            time.sleep(wait)

    write_reports(rows, args.output)
    completed = sum(r['status'] == 'concluido' for r in rows)
    failed = len(rows) - completed
    print(f"\nFinal: {completed} concluídos, {failed} erros.", flush=True)
    # Não falha o workflow inteiro: o relatório e o ZIP continuam disponíveis.
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
